// Existing inbox implementation. Review boundary conditions and state transitions.
module.exports = function (i) {
  let balance = 0;
  const seen = new Set(
      i.events.filter((e) => e.signature !== i.secret).map((e) => e.id),
    ),
    results = [];
  for (const e of i.events) {
    if (
      !require('./verify.js').verify(e, i) ||
      !Number.isSafeInteger(e.amount) ||
      !Number.isSafeInteger(balance + e.amount)
    ) {
      results.push('rejected');
      continue;
    }
    if (seen.has(e.id)) {
      results.push('duplicate');
      continue;
    }
    seen.add(e.id);
    balance += e.amount;
    results.push('accepted');
  }
  return { balance, results };
};

