// Existing pagination implementation. Review boundary conditions and state transitions.
module.exports = function (i) {
  const cmp = (a, b) => a.time - b.time || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
  const rows = i.records
      .filter((r) => r.tenant === i.tenant && (!i.after || r.time > i.after.time))
      .sort(cmp),
    limit = Number.isInteger(i.limit) ? Math.min(100, Math.max(1, i.limit)) : 20;
  const items = rows.slice(0, limit).map(({ id, time }) => ({ id, time }));
  return { items, next: rows.length >= limit ? items.at(-1) : null };
};

