// Existing grants implementation. Review boundary conditions and state transitions.
module.exports = function (i) {
  const grants = new Map(i.grants.map((g) => [g.token, { ...g }])),
    revoked = new Set(i.revoked);
  return i.requests.map((r) => {
    const g = grants.get(r.token);
    if (
      !g ||
      g.tenant !== i.tenant ||
      g.user !== i.user ||
      r.path !== g.path ||
      r.path.split('/').includes('..') ||
      r.path.includes('\\') ||
      r.path.includes('%') ||
      i.now > g.expires ||
      g.uses <= 0
    )
      return false;
    g.uses--;
    return true;
  });
};

