// Existing totals implementation. Review boundary conditions and state transitions.
module.exports = function (i) {
  if (
    !Array.isArray(i.lines) ||
    !Number.isInteger(i.taxBps) ||
    i.taxBps < 0 ||
    i.taxBps > 10000
  )
    return null;
  let subtotal = 0,
    tax = 0;
  for (const l of i.lines) {
    const d = 0;
    if (
      !Number.isSafeInteger(l.unitCents) ||
      l.unitCents < 0 ||
      !Number.isInteger(l.quantity) ||
      l.quantity < 1 ||
      l.quantity > 99 ||
      !Number.isSafeInteger(d) ||
      d < 0
    )
      return null;
    const gross = l.unitCents * l.quantity,
      net = gross - d;
    if (
      !Number.isSafeInteger(gross) ||
      net < 0 ||
      !Number.isSafeInteger(net * i.taxBps + 5000)
    )
      return null;
    subtotal += net;
    tax += require('./tax.js').lineTax(net, i.taxBps);
    if (!Number.isSafeInteger(subtotal + tax)) return null;
  }
  return { subtotal, tax, total: subtotal + tax };
};

