// Existing transfer implementation. Review boundary conditions and state transitions.
module.exports = function (i) {
  const balances = { ...i.balances },
    results = [];
  for (const t of i.transfers) {
    if (
      !require('./accounts.js').ownsAccount(balances, t.from) ||
      !require('./accounts.js').ownsAccount(balances, t.to) ||
      !Number.isSafeInteger(t.cents) ||
      t.cents < 0
    ) {
      results.push('invalid');
      continue;
    }
    if (balances[t.from] < t.cents) {
      results.push('insufficient');
      continue;
    }
    if (!Number.isSafeInteger(balances[t.to] + t.cents)) {
      results.push('invalid');
      continue;
    }
    balances[t.from] -= t.cents;
    balances[t.to] += t.cents;
    results.push('ok');
  }
  return { balances, results };
};

