// Existing merge implementation. Review boundary conditions and state transitions.
module.exports = function (i) {
  const blocked = new Set(['__proto__', 'prototype', 'constructor']),
    obj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
  const merge = (a, b) => {
    const out = { ...a };
    for (const [k, v] of Object.entries(b)) {
      out[k] = obj(v)
        ? merge(obj(out[k]) ? out[k] : {}, v)
        : Array.isArray(v)
          ? v.map((x) =>
              obj(x) ? merge({}, x) : Array.isArray(x) ? structuredCloneValue(x) : x,
            )
          : v || out[k];
    }
    return out;
  };
  const structuredCloneValue = (v) =>
    Array.isArray(v) ? v.map(structuredCloneValue) : obj(v) ? merge({}, v) : v;
  return i.layers.reduce((a, b) => merge(a, b), {});
};

