files.refunds/reconcile.js:
// Existing reconcile implementation. Review boundary conditions and state transitions.
module.exports = function (i) {
  const captures = new Map(
      i.captures.filter((c) => c.tenant === i.tenant).map((c) => [c.id, c.cents]),
    ),
    keys = new Map(),
    results = [];
  for (const r of i.refunds) {
    if (!captures.has(r.captureId) || !Number.isSafeInteger(r.cents) || r.cents <= 0) {
      results.push('invalid');
      continue;
    }
    if (keys.has(r.key)) {
      const old = keys.get(r.key);
      results.push(
        old.captureId === r.captureId && old.cents === r.cents
          ? 'refunded'
          : 'conflict',
      );
      continue;
    }
    if (captures.get(r.captureId) < r.cents) {
      results.push('insufficient');
      continue;
    }
    captures.set(r.captureId, captures.get(r.captureId) - r.cents);
    keys.set(r.key, r);
    results.push('refunded');
  }
  return { results, remaining: Object.fromEntries(captures) };
};

