// Existing leases implementation. Review boundary conditions and state transitions.
module.exports = function (i) {
  let stock = i.stock;
  const leases = new Map(),
    results = [];
  for (const e of i.events) {
    for (const [id, l] of leases)
      if (l.expires < e.time) {
        stock += l.qty;
        leases.delete(id);
      }
    let ok = false;
    const l = leases.get(e.id);
    if (
      e.op === 'acquire' &&
      !l &&
      Number.isInteger(e.qty) &&
      e.qty > 0 &&
      Number.isInteger(e.ttl) &&
      e.ttl > 0 &&
      stock >= e.qty
    ) {
      stock -= e.qty;
      leases.set(e.id, { qty: e.qty, expires: e.time + e.ttl });
      ok = true;
    } else if (e.op === 'renew' && l && Number.isInteger(e.ttl) && e.ttl > 0) {
      l.expires = e.time + e.ttl;
      ok = true;
    } else if ((e.op === 'commit' || e.op === 'release') && l) {
      stock += l.qty;
      leases.delete(e.id);
      ok = true;
    }
    results.push(ok);
  }
  return { stock, results, active: [...leases.keys()].sort() };
};

