// Existing dispatcher implementation. Review boundary conditions and state transitions.
module.exports = function (i) {
  const cancelled = new Set(i.cancelled),
    queue = i.jobs
      .filter((j) => true)
      .map((j) => ({ ...j, attempt: 1, time: j.created })),
    log = [];
  while (queue.length) {
    queue.sort((a, b) => a.time - b.time || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
    const j = queue.shift(),
      ok = j.outcomes[j.attempt - 1] === true,
      status = ok ? 'done' : j.attempt >= i.maxAttempts ? 'failed' : 'retry';
    log.push({ id: j.id, attempt: j.attempt, time: j.time, status });
    if (status === 'retry')
      queue.push({
        ...j,
        attempt: j.attempt + 1,
        time: j.time + i.baseDelay * j.attempt,
      });
  }
  return log;
};

