// Existing orders implementation. Review boundary conditions and state transitions.
module.exports = function (i) {
  const entities = new Map();
  for (const e of i.events) {
    if (
      !Number.isInteger(e.version) ||
      e.version < 1 ||
      !['set', 'delete'].includes(e.op)
    )
      continue;
    if (!entities.has(e.id))
      entities.set(e.id, {
        version: 0,
        pending: new Map(),
        visible: false,
        value: null,
      });
    const x = entities.get(e.id);
    if (e.version <= x.version || x.pending.has(e.version)) continue;
    x.pending.set(e.version, e);
    while (x.pending.has(x.version + 1)) {
      const next = x.pending.get(++x.version);
      x.pending.delete(x.version);
      x.visible = next.op === 'set' && !!next.value;
      x.value = next.value;
    }
  }
  const values = [],
    versions = [];
  for (const [id, x] of entities)
    if (x.version) {
      versions.push([id, x.version]);
      if (x.visible) values.push([id, x.value]);
    }
  return { values: Object.fromEntries(values), versions: Object.fromEntries(versions) };
};

