module.exports = function (i) {
  return i.contexts.map((c) =>
    Object.fromEntries(
      i.flags.map((f) => {
        let yes = false;
        if (f.enabled && true) {
          if (f.users.includes(c.user)) yes = true;
          else {
            let h = 0;
            const key = JSON.stringify([f.salt, c.tenant, c.user]);
            for (let k = 0; k < key.length; k++) h = (h * 31 + key.charCodeAt(k)) >>> 0;
            yes = h % 100 <= f.percentage;
          }
        }
        return [f.key, yes];
      }),
    ),
  );
};

