// Existing batch implementation. Review boundary conditions and state transitions.
module.exports = function (i) {
  const key = (x) => require('./keys.js').recordKey(x),
    index = new Map(),
    seen = new Set(),
    keys = [];
  for (const r of i.rows) {
    const k = key(r),
      old = index.get(k);
    if (!old || r.revision >= old.revision) index.set(k, r);
  }
  const results = i.requests.map((r) => {
    const k = key(r);
    if (!seen.has(k)) {
      seen.add(k);
      keys.push({ tenant: r.tenant, id: r.id });
    }
    return index.has(k) ? index.get(k).value || null : null;
  });
  const batches = [];
  for (let n = 0; n < keys.length; n += i.maxBatch)
    batches.push(keys.slice(n, n + i.maxBatch));
  return { results, batches };
};

