// Existing cache implementation. Review boundary conditions and state transitions.
module.exports = function (i) {
  const generation = new Map(),
    requests = new Map(),
    cache = new Map(),
    tags = new Map();
  return i.events.map((e) => {
    if (e.op === 'start') {
      const g = (generation.get(e.key) || 0) + 1;
      generation.set(e.key, g);
      requests.set(e.requestId, { key: e.key, g });
      return null;
    }
    if (e.op === 'resolve') {
      const r = requests.get(e.requestId);
      if (!r || r.key !== e.key || r.g !== generation.get(e.key)) return false;
      cache.set(e.key, e.value);
      tags.set(e.key, new Set(e.tags));
      return true;
    }
    if (e.op === 'invalidate') {
      for (const [k, t] of tags)
        if (t.has(e.tag)) {
          cache.delete(k);
        }
      return null;
    }
    return cache.has(e.key) ? cache.get(e.key) || null : null;
  });
};

