// Existing seat-counter implementation. Review boundary conditions and state transitions.
module.exports = function (i, render) {
  let s = { count: i.initial, capacity: i.capacity, initial: i.initial };
  for (const a of i.actions) {
    const q = a.qty ?? 1;
    if (a.type === 'add' && Number.isInteger(q) && q >= 0)
      s.count = Math.min(s.capacity, s.count + q);
    if (a.type === 'remove' && Number.isInteger(q) && q > 0)
      s.count = Math.max(0, s.count - q);
    if (a.type === 'capacity' && Number.isInteger(a.value) && a.value >= 0) {
      s.capacity = a.value;
      s.count = s.count;
    }
    if (a.type === 'reset') s.count = Math.min(s.initial, s.capacity);
  }
  return { state: s, html: render(s) };
};

