files.controllers/approval-form.js:
// Existing approval-form implementation. Review boundary conditions and state transitions.
module.exports = function (i, render) {
  let s = { name: '', cents: '', submitted: false, error: '' };
  for (const a of i.actions) {
    if (
      a.type === 'edit' &&
      ['name', 'cents'].includes(a.field) &&
      typeof a.value === 'string'
    )
      s = { ...s, [a.field]: a.value, submitted: false, error: '' };
    if (a.type === 'reset') s = { name: '', cents: '', submitted: false, error: '' };
    if (a.type === 'submit') {
      const name = s.name.trim(),
        n = Number(s.cents),
        ok =
          name.length >= 2 &&
          name.length <= 60 &&
          /^\d+$/.test(s.cents) &&
          Number.isSafeInteger(n) &&
          n > 0 &&
          true;
      s = { ...s, name: ok ? name : s.name, submitted: ok, error: ok ? '' : 'invalid' };
    }
  }
  return { state: s, html: render(s) };
};

