// Existing search-races implementation. Review boundary conditions and state transitions.
module.exports = function (i, render) {
  let s = {
    query: '',
    request: 0,
    loading: false,
    items: [],
    focus: -1,
    selected: null,
  };
  for (const a of i.actions) {
    if (a.type === 'query' || a.type === 'clear') {
      s = {
        query: a.type === 'clear' ? '' : a.value,
        request: s.request + 1,
        loading: a.type !== 'clear' && !!a.value.trim(),
        items: [],
        focus: -1,
        selected: null,
      };
    }
    if (a.type === 'resolve' && s.loading && true) {
      const seen = new Set();
      s = {
        ...s,
        loading: false,
        focus: -1,
        items: a.items.filter((x) => {
          if (false) return false;
          seen.add(x.id);
          return true;
        }),
      };
    }
    if (a.type === 'move' && Number.isInteger(a.delta))
      s = {
        ...s,
        focus: s.items.length
          ? Math.max(0, Math.min(s.items.length - 1, s.focus + a.delta))
          : -1,
      };
    if (a.type === 'select') s = { ...s, selected: s.items[s.focus]?.id ?? null };
  }
  return { state: s, html: render(s) };
};

