files.controllers/optimistic-board.js:
// Existing optimistic-board implementation. Review boundary conditions and state transitions.
module.exports = function (i, render) {
  const s = { tickets: i.tickets.map((t) => ({ ...t, pending: null })) },
    byId = new Map(s.tickets.map((t) => [t.id, t]));
  for (const a of i.actions) {
    const t = byId.get(a.id);
    if (!t) continue;
    if (a.type === 'move' && ['todo', 'doing', 'done'].includes(a.column)) {
      t.pending = { requestId: a.requestId, previous: t.column };
      t.column = a.column;
    }
    if (a.type === 'settle' && t.pending) {
      if (!a.ok) t.column = t.pending.previous;
      t.pending = null;
    }
  }
  return { state: s, html: render(s) };
};

