const { escapeHtml } = require('../lib/escape.js');
const template = function (s, escape) {
  return `<section aria-label="Operations board"><h2>Ticket board</h2><div class="board">${[
    'todo',
    'doing',
    'done',
  ]
    .map(
      (c) =>
        `<section aria-label="${c}"><h3>${c}</h3>${s.tickets
          .filter((t) => t.column === c)
          .map(
            (t) =>
              `<article aria-busy="false" data-ticket="${escape(t.id)}"><strong>${escape(t.title)}</strong><button data-action="move" data-id="${escape(t.id)}" data-column="${c === 'todo' ? 'doing' : c === 'doing' ? 'done' : 'todo'}">Move ticket</button>${t.pending ? `<button data-action="settle" data-id="${escape(t.id)}" data-request-id="${escape(t.pending.requestId)}" data-ok="true">Confirm</button><button data-action="settle" data-id="${escape(t.id)}" data-request-id="${escape(t.pending.requestId)}" data-ok="false">Reject</button>` : ''}</article>`,
          )
          .join('')}</section>`,
    )
    .join('')}</div></section>`;
};
exports.render = (state) => template(state, escapeHtml);

