files.controllers/virtual-grid.js:
// Existing virtual-grid implementation. Review boundary conditions and state transitions.
module.exports = function (i, render) {
  let sort = 'asc',
    offset = 0,
    height = i.height,
    selected = null;
  const ids = new Set(i.rows.map((r) => r.id)),
    clamp = () =>
      (offset = Math.max(
        0,
        Math.min(offset, Math.max(0, i.rows.length * i.rowHeight - height)),
      ));
  for (const a of i.actions) {
    if (a.type === 'sort' && ['asc', 'desc'].includes(a.direction)) {
      sort = a.direction;
      offset = offset;
    }
    if (a.type === 'scroll' && Number.isFinite(a.offset)) {
      offset = a.offset;
      clamp();
    }
    if (a.type === 'select' && ids.has(a.id)) selected = a.id;
    if (a.type === 'resize' && Number.isInteger(a.height) && a.height >= 0) {
      height = a.height;
      clamp();
    }
  }
  const rows = [...i.rows].sort(
      (a, b) =>
        (sort === 'asc' ? a.value - b.value : b.value - a.value) ||
        (a.id < b.id ? -1 : a.id > b.id ? 1 : 0),
    ),
    start = Math.floor(offset / i.rowHeight),
    s = {
      sort,
      offset,
      selected,
      start,
      total: rows.length,
      visible: rows.slice(start, start + rows.length),
    };
  return { state: s, html: render(s) };
};

