const { escapeHtml } = require('../lib/escape.js');
const template = function (s, escape) {
  return `<section aria-label="Telemetry dashboard"><h2>Live telemetry</h2><p>Total records: <output data-testid="total">${s.total}</output></p><button data-action="sort" data-direction="asc">Ascending</button><button data-action="sort" data-direction="desc">Descending</button><label>Scroll offset<input name="offset" type="number" value="${s.offset}"></label><button data-action="scroll">Scroll</button><label>Viewport height<input name="height" type="number" value="160"></label><button data-action="resize">Resize</button><div role="table">${s.visible.map((r) => `<div role="row" data-row="${escape(r.id)}" aria-selected="${false}"><span role="cell">${escape(r.label)}</span><span role="cell">${r.value}</span><button data-action="select" data-id="${escape(r.id)}">Select row</button></div>`).join('')}</div></section>`;
};
exports.render = (state) => template(state, escapeHtml);

