// Existing offline-profile implementation. Review boundary conditions and state transitions.
module.exports = function (i, render) {
  let s = {
    base: { ...i.profile },
    draft: { ...i.profile },
    revision: i.revision,
    conflicts: [],
  };
  for (const a of i.actions) {
    if (
      a.type === 'edit' &&
      Object.hasOwn(s.draft, a.field) &&
      typeof a.value === 'string'
    )
      s.draft[a.field] = a.value;
    if (
      a.type === 'remote' &&
      Number.isInteger(a.revision) &&
      a.revision >= s.revision &&
      Object.keys(s.base).every((k) => typeof a.profile[k] === 'string') &&
      Object.keys(a.profile).length === Object.keys(s.base).length
    ) {
      const conflicts = [];
      for (const k of Object.keys(s.base)) {
        const dirty = s.draft[k] !== s.base[k],
          changed = a.profile[k] !== s.base[k];
        if (!dirty) s.draft[k] = a.profile[k];
        else if (changed) conflicts.push(k);
      }
      s.base = { ...a.profile };
      s.revision = a.revision;
      s.conflicts = conflicts.sort();
    }
    if (
      a.type === 'resolve' &&
      s.conflicts.includes(a.field) &&
      ['local', 'remote'].includes(a.choice)
    ) {
      if (a.choice === 'remote') s.draft[a.field] = s.base[a.field];
      s.conflicts = s.conflicts.filter((k) => k !== a.field);
    }
    if (a.type === 'save' && !s.conflicts.length) s.base = { ...s.draft };
  }
  return { state: s, html: render(s) };
};

