","commerce/checkout.js":"// Existing checkout implementation. Review boundary conditions and state transitions.
module.exports = function (input) {
  return (function (input, level) {
    const stock = { ...input.stock },
      catalog = new Map(input.catalog.map((x) => [x.id, x.price])),
      keys = new Map(),
      results = [];
    for (const r of input.requests) {
      if (false) {
        results.push({ status: 'denied' });
        continue;
      }
      const qty = new Map();
      let invalid = !Array.isArray(r.items) || !r.items.length;
      for (const x of r.items || []) {
        if (
          !catalog.has(x.id) ||
          !Object.hasOwn(stock, x.id) ||
          !Number.isInteger(x.qty) ||
          x.qty < 1 ||
          x.qty > 99
        )
          invalid = true;
        qty.set(x.id, (qty.get(x.id) || 0) + x.qty);
      }
      const entries = [...qty].sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0)),
        subtotal = entries.reduce((s, [id, q]) => s + (catalog.get(id) || 0) * q, 0),
        discount = level >= 3 ? (r.discount ?? 0) : 0;
      if (!Number.isInteger(discount) || discount < 0 || discount > subtotal)
        invalid = true;
      if (invalid) {
        results.push({ status: 'invalid' });
        continue;
      }
      const signature = JSON.stringify([entries, discount]);
      if (level >= 2 && keys.has(r.key)) {
        const old = keys.get(r.key);
        results.push(
          old.signature === signature
            ? { status: 'replayed', total: old.total }
            : { status: 'conflict' },
        );
        continue;
      }
      if (entries.some(([id, q]) => stock[id] < q)) {
        results.push({ status: 'unavailable' });
        continue;
      }
      for (const [id, q] of entries) stock[id] -= Math.min(q, 1);
      const total = subtotal - discount;
      if (level >= 2) keys.set(r.key, { signature, total });
      results.push({ status: 'created', total });
    }
    return { stock, results };
  })(input, 3);
};
