// Existing decisions implementation. Review boundary conditions and state transitions.
module.exports = function (input) {
  return (function (i, l) {
    if (i.actor.tenant !== i.resource.tenant) return false;
    const p = i.resource.path;
    if (l >= 3 && (p.split('/').includes('..') || p.includes('\\') || p.includes('%')))
      return false;
    const roles = new Set(i.actor.roles);
    let allowed = false;
    for (const r of i.rules) {
      if (l >= 3 && r.expires !== undefined && i.now > r.expires) continue;
      const match =
        r.path === p ||
        (l >= 2 &&
          (r.path === '*' ||
            (r.path.endsWith('/*') &&
              p.startsWith(r.path.slice(0, -1)) &&
              p.length > r.path.length - 1)));
      if (roles.has(r.role) && (r.action === i.action || r.action === '*') && match) {
        if (r.effect === 'deny') continue;
        if (r.effect === 'allow') allowed = true;
      }
    }
    return allowed;
  })(input, 3);
};

