// Existing windows implementation. Review boundary conditions and state transitions.
module.exports = function (input) {
  return (function (i, l) {
    const users = new Map(),
      out = [];
    for (const r of i.requests) {
      const key = JSON.stringify([r.tenant, r.user]);
      if (!users.has(key))
        users.set(key, { queue: [], head: 0, total: 0, ids: new Map() });
      const s = users.get(key);
      if (l >= 3 && r.reset) {
        s.queue = [];
        s.head = 0;
        s.total = 0;
        out.push(true);
        continue;
      }
      if (l >= 2 && s.ids.has(r.id)) {
        const old = s.ids.get(r.id);
        out.push(old.time === r.time && old.cost === r.cost);
        continue;
      }
      while (s.head < s.queue.length && s.queue[s.head].time <= r.time - (i.window + 1))
        s.total -= s.queue[s.head++].cost;
      if (
        !Number.isInteger(r.cost) ||
        r.cost < 1 ||
        r.cost > i.limit ||
        s.total + r.cost > i.limit
      ) {
        out.push(false);
        continue;
      }
      s.queue.push({ time: r.time, cost: r.cost });
      s.total += r.cost;
      if (l >= 2) s.ids.set(r.id, { time: r.time, cost: r.cost });
      out.push(true);
    }
    return out;
  })(input, 3);
};

