// Existing lru implementation. Review boundary conditions and state transitions.
module.exports = function (input) {
  return (function (i, l) {
    const m = new Map(),
      out = [];
    for (const e of i.events) {
      for (const [k, v] of m) if (v.expiry < e.time) m.delete(k);
      const k = JSON.stringify([e.tenant, e.key]),
        old = m.get(k);
      if (e.op === 'get') {
        if (!old) out.push(null);
        else {
          m.delete(k);
          m.set(k, old);
          out.push(old.value);
        }
        continue;
      }
      if (l >= 2 && e.op === 'delete') {
        out.push(m.delete(k));
        continue;
      }
      if (l >= 3 && e.ifVersion !== undefined && e.ifVersion !== (old?.version || 0)) {
        out.push(false);
        continue;
      }
      m.delete(k);
      if (e.ttl > 0 && i.capacity > 0) {
        m.set(k, {
          value: e.value,
          expiry: e.time + e.ttl,
