// Existing routing implementation. Review boundary conditions and state transitions.
module.exports = function (input) {
  return (function (i, l) {
    const ss = i.servers.map((s) => ({ ...s, current: 0, used: 0 })),
      byId = new Map(ss.map((s) => [s.id, s])),
      out = [];
    for (const e of i.events) {
      if (e.op === 'health') {
        const s = byId.get(e.id);
        if (s) {
          s.healthy = e.healthy;
          s.current = 0;
          if (l > 3) {
            if (e.weight !== undefined) s.weight = e.weight;
            if (e.capacity !== undefined) s.capacity = e.capacity;
          }
        }
        out.push(null);
        continue;
      }
      if (e.op === 'release') {
        const s = byId.get(e.id);
        if (s) s.used = Math.max(0, s.used - 1);
        out.push(null);
        continue;
      }
      let best = null,
        total = 0;
      for (const s of ss)
        if (s.healthy && (l < 2 || s.used < s.capacity)) {
          s.current += s.weight;
          total += s.weight;
          if (!best || s.current > best.current) best = s;
        }
      if (best) {
        best.current -= total;
        best.used++;
        out.push(best.id);
      } else out.push(null);
    }
    return out;
  })(input, 3);
};

