// Existing planner implementation. Review boundary conditions and state transitions.
module.exports = function (input) {
  return (function (i, l) {
    const map = new Map(i.jobs.map((j) => [j.id, j]));
    if (
      i.jobs.some(
        (j) => j.deps.some((d) => !map.has(d)) || (l >= 2 && j.cpu >= i.budget),
      )
    )
      return null;
    const done = new Set(),
      out = [];
    while (done.size < i.jobs.length) {
      const ready = i.jobs
        .filter((j) => !done.has(j.id) && j.deps.every((d) => done.has(d)))
        .sort(
          (a, b) =>
            (l >= 2 ? b.priority - a.priority : 0) ||
            (a.id < b.id ? -1 : a.id > b.id ? 1 : 0),
        );
      let used = 0;
      const wave = [],
        locks = new Set();
      for (const j of ready) {
        if (l >= 2 && used + j.cpu > i.budget) continue;
        if (l >= 3 && ((j.mutex && locks.has(j.mutex)) || (j.exclusive && wave.length)))
          continue;
        wave.push(j.id);
        used += j.cpu;
        if (j.mutex) locks.add(j.mutex);
        if (l >= 3 && j.exclusive) break;
      }
      if (!wave.length) return null;
      out.push(wave);
      wave.forEach((id) => done.add(id));
    }
    return out;
  })(input, 3);
};

