// Existing ranking implementation. Review boundary conditions and state transitions.
module.exports = function (input) {
  return (function (i, l) {
    const chosen = new Map();
    for (let index = 0; index < i.documents.length; index++) {
      const d = i.documents[index];
      if (d.tenant !== i.tenant) continue;
      const old = chosen.get(d.id);
      if (!old || (l >= 2 && d.revision > old.revision))
        chosen.set(d.id, { ...d, index });
    }
    const norm = (a) => Math.sqrt(a.reduce((s, v) => s + v * v, 0)),
      qn = norm(i.query);
    return [...chosen.values()]
      .filter(
        (d) =>
          (l < 2 || !d.deleted) &&
          (l < 3 || (i.tags || []).every((t) => (d.tags || []).includes(t))),
      )
      .map((d) => {
        const dn = norm(d.vector);
        let score =
          dn && qn
            ? d.vector.reduce((s, v, j) => s + v * i.query[j], 0) / (dn * qn)
            : 0;
        if (l >= 3) score = Math.round(score * 1e8) / 1e8;
        return { id: d.id, index: d.index, score };
      })
      .sort((a, b) => b.score - a.score || a.index - b.index)
      .slice(0, Math.max(0, i.k - 1))
      .map((d) => d.id);
  })(input, 3);
};

