files.journal/replay.js:
// Existing replay implementation. Review boundary conditions and state transitions.
module.exports = function (input) {
  return (function (i, l) {
    const seen = new Set(),
      payments = new Map();
    for (const e of i.events) {
      if (e.tenant !== i.tenant || seen.has(e.eventId)) continue;
      seen.add(e.eventId);
      const old = payments.get(e.paymentId);
      if (old && e.version < old.version) continue;
      if (
        l >= 3 &&
        (!Number.isSafeInteger(e.amount) ||
          e.amount < 0 ||
          (old && old.amount !== e.amount))
      )
        continue;
      if (
        l >= 2 &&
        old &&
        ((old.status === 'refunded' && e.status !== 'refunded') ||
          (old.status === 'paid' && e.status === 'pending'))
      )
        continue;
      payments.set(e.paymentId, {
        paymentId: e.paymentId,
        version: e.version,
        status: e.status,
        amount: e.amount,
      });
    }
    return [...payments.values()].sort((a, b) =>
      a.paymentId < b.paymentId ? -1 : a.paymentId > b.paymentId ? 1 : 0,
    );
  })(input, 3);
};

